select 
from sys_hr_sign_event_outbox
where action_id = #{actionId}
  and event_version = #{eventVersion}
limit 1

select 
from sys_hr_sign_event_outbox
where (
        status in ('PENDING', 'RETRY')
        and (next_retry_time is null or next_retry_time <= #{dueTime})
      )
   or (
        status = 'SENDING'
        and update_time <= #{staleSendingBefore}
      )
order by coalesce(next_retry_time, create_time), outbox_id
limit #{limit}

mapper.update:
update sys_hr_sign_event_outbox
set status = 'SENDING',
    version = version + 1,
    update_time = sysdate()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and version = #{version}
